def solve(inputs: dict) -> float:
    M = inputs['matrix']
    power = inputs['power']
    modulus = inputs['modulus']

    # Convert to list of lists if needed
    if not isinstance(M[0], list):
        M = [list(row) for row in M]

    n = len(M)

    def matrix_mult(A, B, mod):
        """Multiply two n×n matrices modulo mod"""
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, exp, mod):
        """Compute M^exp modulo mod using binary exponentiation"""
        if exp == 0:
            # Return identity matrix
            result = [[0] * n for _ in range(n)]
            for i in range(n):
                result[i][i] = 1
            return result

        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1  # Identity matrix

        base = [row[:] for row in M]  # Copy M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_pow(M, power, modulus)

    # Sum all entries
    total = 0
    for row in result_matrix:
        for entry in row:
            total += entry

    return float(total)

